//! Tests of the semantic search, model side: fp16 storage, image preprocessing (parity with PIL on the Phase 0 fixtures), query
//! normalisation. Synthetic images only (the PNG fixtures are generated by dev_tools/semantic/make_reference.py).
//!
//! Parity tests with the real model are `#[ignore]`: run them with
//!   SEMANTIC_MODEL_DIR=<folder with vision.onnx, text.onnx, tokenizer.json> cargo test semantic:: -- --ignored
//! The ONNX Runtime library is read from ORT_DYLIB_PATH, otherwise from the `models/` folder of an installed application.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use rusqlite::{params, Connection};

use super::*;
use crate::semantic_models::active_model;

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join("tests").join("fixtures")
}

fn reference() -> serde_json::Value {
    serde_json::from_str(include_str!("fixtures/semantic_reference.json")).expect("semantic_reference.json")
}

fn cosine(a: &[f32], b: &[f32]) -> f64 {
    let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
    let norm = |v: &[f32]| v.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
    dot / (norm(a) * norm(b))
}

fn floats(value: &serde_json::Value) -> Vec<f32> {
    value.as_array().expect("array").iter().map(|item| item.as_f64().expect("number") as f32).collect()
}

