#[test]
fn resize_keeps_a_uniform_image_uniform_and_skips_unchanged_sizes() {
    let rgb: Vec<u8> = [17u8, 128, 250].repeat(37 * 23);
    let resized = resize_bilinear(&rgb, 37, 23, 224, 224);
    assert_eq!(resized.len(), 224 * 224 * 3);
    assert!(resized.chunks_exact(3).all(|pixel| pixel == [17, 128, 250]));
    let pattern: Vec<u8> = (0..20 * 10 * 3).map(|index| (index * 7 % 256) as u8).collect();
    assert_eq!(resize_bilinear(&pattern, 20, 10, 20, 10), pattern);
}

#[test]
fn image_tensor_has_the_model_shape_and_range() {
    let model = active_model();
    let rgb: Vec<u8> = (0..300 * 200 * 3).map(|index| (index * 13 % 256) as u8).collect();
    let tensor = image_tensor(&rgb, 300, 200, model);
    assert_eq!(tensor.len(), 3 * model.image_size * model.image_size);
    assert!(tensor.iter().all(|value| (-1.0..=1.0).contains(value)));
    // Black and white map to the ends of the range.
    let black = image_tensor(&[0u8; 3 * 4], 2, 2, model);
    let white = image_tensor(&[255u8; 3 * 4], 2, 2, model);
    assert!(black.iter().all(|&value| value == -1.0) && white.iter().all(|&value| value == 1.0));
}

#[test]
fn preprocessing_matches_pil_on_the_reference_images() {
    let model = active_model();
    let size = model.image_size;
    // Positions (channel, y, x) of the probes written by make_reference.py.
    let positions = [(0usize, 0usize, 0usize), (1, 111, 57), (2, 223, 223), (0, 100, 200)];
    for image in reference()["images"].as_array().unwrap() {
        let file = image["file"].as_str().unwrap();
        let (rgb, width, height) = crate::integrity::decode_png(&fixtures_dir().join(file), true).expect("fixture PNG");
        let tensor = image_tensor(&rgb, width, height, model);
        let expected = floats(&image["pixel_probe"]);
        for ((channel, y, x), want) in positions.iter().zip(expected) {
            let got = tensor[channel * size * size + y * size + x];
            assert!((got - want).abs() < 1e-3, "{file} ({channel}, {y}, {x}): {got} instead of {want}");
        }
    }
}

